// Worked solutions for bank questions outside the public samples, in three
// layers: `hint` (a nudge before answering, without the answer), `shortcut`
// (the quick way under exam time) and `solution` (the full reasoning).
// build.mjs adds them to their questions and refuses to build if `answer`
// (the option the solution reaches) differs from the key. Written by Claude
// and waiting for the owner's review (noted on each question).
//
// Key: the question's external id. Only questions whose text and final key
// were checked; a key the mathematics does not reach is logged in
// ../bank-corrections.md instead of solved here.

const t = (text) => ({ type: "text", text });

// The same question printed in two booklets of one year shares its solution.
const GROWTH_LOG_FACTORIAL = {
  answer: 2,
  hint: String.raw`$(\log n)!$ را به شکل توانی از $n$ بنویس: با $m=\log n$، $m!$ تقریباً $m^m$ است.`,
  shortcut: String.raw`$\log n!=\Theta(n\log n)$ از $n$ بزرگ‌تر است، و $(\log n)!=n^{\Theta(\log\log n)}$ از هر چندجمله‌ای بزرگ‌تر؛ ترتیب: $n<\log n!<(\log n)!$؛ گزینهٔ ۲.`,
  solution: [
    t(String.raw`$\log n!=\sum_{k=1}^n\log k=\Theta(n\log n)$، پس $n=o(\log n!)$. این گزینه‌های ۳ و ۴ را که $\log n!$ را کوچک‌تر از $n$ گذاشته‌اند رد می‌کند.`),
    t(String.raw`برای $(\log n)!$ قرار بده $m=\log n$. داریم $m!\ge(\frac m2)^{m/2}=2^{\frac m2\log\frac m2}$؛ با $2^m=n$ این برابر $n^{\Theta(\log\log n)}$ است، یعنی از هر چندجمله‌ای در $n$، از جمله $n\log n$، سریع‌تر رشد می‌کند.`),
    t(String.raw`پس $O(n)<O(\log n!)<O((\log n)!)$؛ گزینهٔ ۲.`),
    t(String.raw`دام تست: $\log n!$ و $(\log n)!$ فقط در جای پرانتز فرق دارند. اولی لگاریتمِ یک فاکتوریل بزرگ است (حدود $n\log n$)، دومی فاکتوریلِ یک عدد کوچک که باز هم فوق چندجمله‌ای است.`),
  ],
};
const GROWTH_LOG_POWER = {
  answer: 2,
  hint: String.raw`$(\log n)^{\log n}$ را به شکل $n^{\dots}$ بنویس.`,
  shortcut: String.raw`$(\log n)^{\log n}=2^{\log n\cdot\log\log n}=n^{\log\log n}$ که از $n$ سریع‌تر رشد می‌کند؛ پس $n\in O((\log n)^{\log n})$؛ گزینهٔ ۲.`,
  solution: [
    t(String.raw`$(\log n)^{\log n}=2^{\log n\cdot\log\log n}=(2^{\log n})^{\log\log n}=n^{\log\log n}$. چون $\log\log n\to\infty$، این تابع از هر چندجمله‌ای سریع‌تر رشد می‌کند. پس گزینهٔ ۲ درست و گزینهٔ ۱ (برعکس آن) نادرست است.`),
    t(String.raw`گزینهٔ ۳: $\log n!=\Theta(n\log n)$ و در $O(n)$ نیست.`),
    t(String.raw`گزینهٔ ۴: $(\log n)!$ هم مثل $(\log n)^{\log n}$ برابر $n^{\Theta(\log\log n)}$ است و از $n$ بزرگ‌تر؛ پس $n\notin\Omega((\log n)!)$.`),
  ],
};
