    shortcut: String.raw`حذف آخرین گره یعنی گره ماقبل آخر باید آخر شود، و در لیست یک‌طرفه برای رسیدن به آن باید از ابتدا پیمود: $O(n)$. سه عمل دیگر با اشاره‌گرهای ابتدا و انتها $O(1)$ هستند؛ گزینهٔ ۱.`,
