  "kunkurcomputer-q-1209-1398-861A-082": {
    answer: 3,
    hint: String.raw`کمترین گره در AVL با ارتفاع $h$: ریشه + کمینهٔ ارتفاع $h-1$ + کمینهٔ ارتفاع $h-2$.`,
    shortcut: String.raw`$N(h)=N(h-1)+N(h-2)+1$ با $N(0)=1$، $N(1)=2$: ۴، ۷، ۱۲، ۲۰؛ پس کمینه ۲۰. بیشینه درخت پر: $2^6-1=63$؛ گزینهٔ ۳.`,
    solution: [
      t(String.raw`کم‌گره‌ترین درخت AVL با ارتفاع $h$: یک زیردرخت ارتفاع $h-1$ و دیگری ارتفاع $h-2$ (بیشترین اختلاف مجاز)، هر دو کم‌گره‌ترین. پس $N(h)=1+N(h-1)+N(h-2)$.`),
      t(String.raw`با عمق ریشه صفر: $N(0)=1$، $N(1)=2$، $N(2)=4$، $N(3)=7$، $N(4)=12$، $N(5)=20$.`),
      t(String.raw`پرگره‌ترین: درخت دودویی پر با سطح‌های ۰ تا ۵: $2^6-1=63$ گره. جواب ۲۰ و ۶۳؛ گزینهٔ ۳. (دام: با تعریف «ارتفاع درخت تک‌گره ۱»، اعداد یک پله جابه‌جا می‌شوند و ۱۲ و ۳۱ به دست می‌آید.)`),
    ],
  },
  "kunkurcomputer-q-1277-1389-b1-031": {
    answer: 3,
    hint: String.raw`هزینهٔ عمل‌هایی که اندیسشان توانی از ۲ است را جدا جمع بزن.`,
    shortcut: String.raw`توان‌های ۲ تا $2^n$: $1+2+\dots+2^n=2^{n+1}-1$. بقیهٔ عمل‌ها (حدود $2^n$ تا) هر کدام ۱. جمع حدود $3\cdot2^n$، تقسیم بر $2^n$: نزدیک ۳؛ گزینهٔ ۳.`,
    solution: [
      t(String.raw`عمل‌های $i=1,\dots,2^n$. آن‌هایی که $i$ توان ۲ است: $i=1,2,4,\dots,2^n$ ($n+1$ عمل) با هزینهٔ کل $2^{n+1}-1$.`),
      t(String.raw`بقیه $2^n-(n+1)$ عمل با هزینهٔ ۱. هزینهٔ کل: $2^{n+1}-1+2^n-n-1=3\cdot2^n-n-2$.`),
      t(String.raw`میانگین: $\frac{3\cdot2^n-n-2}{2^n}=3-\frac{n+2}{2^n}\to3$؛ گزینهٔ ۳. این همان تحلیل سرشکن آرایهٔ پویا با دو برابر کردن ظرفیت است: عمل‌های گران نادرند و هزینهٔ سرشکن هر عمل ثابت می‌ماند.`),
    ],
  },
