    shortcut: String.raw`جواب به عملگرها بستگی دارد: در $a+b+c$ هر دو پرانتزگذاری یک مقدار می‌دهند، ولی در $a-b-c$ فقط یکی؛ پس عدد ثابتی نمی‌شود گفت؛ گزینهٔ ۴.`,
