  "kunkurcomputer-q-1209-1383-b0-132": {
    answer: 3,
    hint: String.raw`وارون یک الحاق، الحاق وارون‌ها به ترتیب برعکس است: $(xy)^R=y^Rx^R$.`,
    shortcut: String.raw`$(ba)^R=ab$، $(b^*(ab)^*)^R=(ba)^*b^*$ و $(a^*(bb)^*)^R=(bb)^*a^*$. پس $L^R=ab((ba)^*b^*+(bb)^*a^*)ab$؛ گزینهٔ ۳.`,
    solution: [
      t(String.raw`قواعد: $(r_1r_2)^R=r_2^Rr_1^R$، $(r_1+r_2)^R=r_1^R+r_2^R$ و $(r^*)^R=(r^R)^*$.`),
      t(String.raw`$L=ba\cdot X\cdot ba$ با $X=b^*(ab)^*+a^*(bb)^*$. پس $L^R=(ba)^R\,X^R\,(ba)^R=ab\,X^R\,ab$.`),
      t(String.raw`$X^R=((ab)^*)^R(b^*)^R+((bb)^*)^R(a^*)^R=(ba)^*b^*+(bb)^*a^*$. جواب: گزینهٔ ۳. (دام: در گزینهٔ ۱، $(ab)^*$ برعکس نشده است.)`),
    ],
  },
  "kunkurcomputer-q-1209-1383-b0-136": {
    answer: 4,
    hint: String.raw`یک رشتهٔ ساده از $(\alpha+\beta)^*$ پیدا کن که در عبارت سمت راست نباشد.`,
    shortcut: String.raw`$\beta\beta\in(\alpha+\beta)^*$ ولی در $\alpha^*(\beta\alpha)^*$ بعد از هر $\beta$ باید یک $\alpha$ بیاید؛ پس گزینهٔ ۴ ممکن است نادرست باشد.`,
    solution: [
      t(String.raw`گزینهٔ ۴: با $\alpha=a$ و $\beta=b$، $bb\in(a+b)^*$ ولی $a^*(ba)^*$ هیچ دو $b$ پشت هم ندارد. پس این رابطه در حالت کلی نادرست است.`),
      t(String.raw`بقیه همانی‌های معروف‌اند: (۱) $(\alpha^*\beta^*)^*$ شامل $\alpha$ و $\beta$ است و هر الحاقی از آن‌ها را می‌سازد؛ (۲) همین‌طور $(\alpha^*+\beta^*)^*$؛ (۳) $\alpha^*(\beta\alpha^*)^*$: رشته را با هر $\beta$ تکه کن؛ تکهٔ اول $\alpha^*$ و هر تکهٔ بعدی $\beta\alpha^*$ است. جواب: گزینهٔ ۴.`),
    ],
  },
  "kunkurcomputer-q-1209-1385-b0-118": {
    answer: 3,
    hint: String.raw`شرط‌های $n,m,k\ge1$ را فراموش نکن: $a^*$ رشتهٔ تهی را هم می‌دهد.`,
    shortcut: String.raw`$a^n$ با $n\ge1$: $aa^*$؛ $b^{3m}$ با $m\ge1$: $(bbb)^*bbb$؛ $c^{2k}$ با $k\ge1$: $(cc)^*cc$. گزینهٔ ۳.`,
    solution: [
      t(String.raw`هر بخش جدا: $a^n,n\ge1$ یعنی $aa^*$ (یا $a^+$). $b^{3m},m\ge1$ یعنی $bbb(bbb)^*$. $c^{2k},k\ge1$ یعنی $cc(cc)^*$. الحاقشان دقیقاً گزینهٔ ۳ است.`),
      t(String.raw`گزینهٔ ۱ رشتهٔ تهی و حالت‌های $n=0$ و غیره را هم می‌پذیرد. گزینهٔ ۲ هر تعداد $b$ و $c$ را می‌پذیرد (مضرب ۳ و ۲ بودن را حفظ نمی‌کند). گزینهٔ ۴ مثلاً $abbbbccc$ را می‌پذیرد که چهار $b$ و سه $c$ دارد. جواب: گزینهٔ ۳.`),
    ],
  },
  "kunkurcomputer-q-1209-1399-462F-088": {
    answer: 2,
    hint: String.raw`هر تکهٔ $01^*01^+$ را به تکه‌های $L'$ بشکن. برعکسش: $01$ در $L'$ هست؛ در $L$ چه؟`,
    shortcut: String.raw`تکهٔ $01^i01^j$ اگر $i\ge1$ باشد دو تکهٔ $01^+$ و اگر $i=0$ یک تکهٔ $001^+$ است؛ پس $L\subseteq L'$. ولی $01\in L'$ و $01\notin L$ (تعداد ۰ها در $L$ زوج است)؛ $L\subsetneq L'$؛ گزینهٔ ۲.`,
    solution: [
      t(String.raw`$L\subseteq L'$: هر تکهٔ $L$ به شکل $01^i01^j$ با $j\ge1$ است. اگر $i\ge1$، این همان $(01^i)(01^j)$ است که هر دو از شکل $01^+$ هستند. اگر $i=0$، این $001^j$ است که از شکل $001^+$ است. پس هر رشتهٔ $L$ در $L'$ است.`),
      t(String.raw`سره بودن: هر تکهٔ $L$ دقیقاً دو ۰ دارد، پس تعداد ۰های هر رشتهٔ $L$ زوج است. ولی $01\in L'$ یک ۰ دارد. پس $L\ne L'$ و $L\subsetneq L'$؛ گزینهٔ ۲.`),
    ],
  },
  "kunkurcomputer-q-1209-1405-257A-087": {
    answer: 2,
    hint: String.raw`قانون «ب» در $L_1$ از چپ $aab$ و از راست $bb$ اضافه می‌کند. این دو مستقل از هم‌اند؟`,
    shortcut: String.raw`با $i$ بار اضافه‌کردن $aab$ در چپ و $j$ بار $bb$ در راست (به هر ترتیبی) $(aab)^i(bb)^j$ به دست می‌آید و هر چنین رشته‌ای ساخته می‌شود؛ پس $L_1=(aab)^*(bb)^*=L_2$؛ گزینهٔ ۲.`,
    solution: [
      t(String.raw`$L_1\subseteq L_2$: با استقرا روی تعداد قانون‌ها، هر عضو $L_1$ به شکل $(aab)^i(bb)^j$ است: $\lambda$ این شکل را دارد، و اگر $x=(aab)^i(bb)^j$ باشد، $aabx=(aab)^{i+1}(bb)^j$ و $xbb=(aab)^i(bb)^{j+1}$.`),
      t(String.raw`$L_2\subseteq L_1$: از $\lambda$ شروع کن، $j$ بار قانون $xbb$ و بعد $i$ بار قانون $aabx$ را بزن تا $(aab)^i(bb)^j$ ساخته شود.`),
      t(String.raw`پس $L_1=L_2$؛ گزینهٔ ۲.`),
    ],
  },
