    shortcut: "آدرس = tag | index | offset. tag بخش بالای آدرس فیزیکی است که کنار هر بلوک ذخیره می‌شود تا معلوم شود بلوک داخل cache مال کدام آدرس است؛ گزینهٔ ۴.",
