    shortcut: String.raw`از گوشهٔ بالا-راست: اگر عنصر بزرگ‌تر از $x$ بود یک ستون چپ، اگر کوچک‌تر بود یک سطر پایین. حداکثر $2n-1$ گام، یعنی حداکثر حدود $2n$ مقایسه؛ گزینهٔ ۱.`,
