  "kunkurcomputer-q-1277-1390-b2-033": {
    answer: 1,
    hint: String.raw`در هر گام $\frac k2$امین عنصر دو آرایه را مقایسه کن و نیمی از نامزدها را کنار بگذار.`,
    shortcut: String.raw`$A_1[\frac k2]$ و $A_2[\frac k2]$ را مقایسه کن؛ $\frac k2$ عنصر اول آرایه‌ای که مقدار کوچک‌تر دارد نمی‌تواند $k$امین باشد و حذف می‌شود. $k$ هر بار نصف می‌شود: $O(\lg n)$؛ گزینهٔ ۱.`,
    solution: [
      t(String.raw`فرض $A_1[\frac k2]<A_2[\frac k2]$. همهٔ $\frac k2$ عنصر اول $A_1$ حداکثر $k-1$ عنصر کوچک‌تر از خود دارند ($\frac k2-1$ از $A_1$ و کمتر از $\frac k2$ از $A_2$)، پس هیچ‌کدام $k$امین نیست. آن‌ها را کنار می‌گذاریم و دنبال $(k-\frac k2)$امین عنصر در باقی‌مانده می‌گردیم.`),
      t(String.raw`هر گام $k$ را نصف می‌کند و $O(1)$ کار دارد، پس $O(\lg k)\subseteq O(\lg n)$؛ گزینهٔ ۱. ادغام کامل $O(k)$ لازم نیست.`),
    ],
  },
