    shortcut: String.raw`BST با درج کلیدهای مرتب یک زنجیر با عمق $n-1$ می‌شود: $O(n)$. هرم درخت کامل است و عمقش $O(\log n)$؛ پس فقط گزینهٔ ۳ درست است.`,
